<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><section class="records-dashboard"><header class="dashboard-heading"><div><h1>Welcome Back, <?= esc($adminUser['full_name'] ?? 'Administrator') ?>!</h1><p>Student Records Management</p></div></header><div class="metric-grid records-metrics"><article class="metric-card"><span class="material-symbols-outlined">school</span><small>Total Students</small><strong><?= (int)$total ?></strong></article><article class="metric-card"><span class="material-symbols-outlined">how_to_reg</span><small>Enrolled</small><strong><?= (int)$enrolled ?></strong></article><article class="metric-card"><span class="material-symbols-outlined">verified</span><small>Successful Verifications</small><strong><?= (int)$successful ?></strong></article><article class="metric-card"><span class="material-symbols-outlined">error</span><small>Unsuccessful Verifications</small><strong><?= (int)$unsuccessful ?></strong></article><article class="metric-card"><span class="material-symbols-outlined">assignment</span><small>Verification Requests</small><strong><?= (int)$requests ?></strong></article></div><div class="dashboard-grid"><article class="dashboard-panel"><header><h2>Verification Overview</h2><a href="<?= site_url('admin/verification-management') ?>">View logs</a></header><div class="status-grid"><div><span class="status-dot verified"></span><small>Verified events</small><strong><?= (int)$successful ?></strong></div><div><span class="status-dot unsuccessful"></span><small>Other outcomes</small><strong><?= (int)$unsuccessful ?></strong></div></div></article><article class="dashboard-panel"><header><h2>Verification Request Status</h2></header><div class="status-grid"><?php foreach($requestCounts as $status=>$count): ?><div><span class="status-dot <?= esc($status,'attr') ?>"></span><small><?= esc(ucwords(str_replace('_',' ',$status))) ?></small><strong><?= (int)$count ?></strong></div><?php endforeach ?></div></article><article class="dashboard-panel recent-panel"><header><h2>Recent Verification Activity</h2><a href="<?= site_url('admin/verification-management') ?>">All activity</a></header><?php if($recentVerifications): ?><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Result</th><th>Category</th></tr></thead><tbody><?php foreach($recentVerifications as $log): ?><tr><td><?= esc($log['requested_at']) ?></td><td><span class="status-badge <?= esc($log['verification_result'],'attr') ?>"><?= esc(ucwords(str_replace('_',' ',$log['verification_result']))) ?></span></td><td><?= esc($log['response_category']) ?></td></tr><?php endforeach ?></tbody></table></div><?php else:?><p class="empty">No verification activity yet.</p><?php endif ?></article><article class="dashboard-panel recent-panel"><header><h2>Recent Assistance Requests</h2><a href="<?= site_url('admin/verification-management?tab=requests') ?>">All requests</a></header><?php if($recentRequests): ?><div class="table-wrap"><table><thead><tr><th>Request</th><th>Student</th><th>Status</th></tr></thead><tbody><?php foreach($recentRequests as $request): ?><tr><td><a href="<?= site_url('admin/verification-requests/'.$request['id']) ?>">#<?= (int)$request['id'] ?></a></td><td><?= esc($request['full_name']) ?></td><td><span class="status-badge <?= esc($request['status'],'attr') ?>"><?= esc(ucwords(str_replace('_',' ',$request['status']))) ?></span></td></tr><?php endforeach ?></tbody></table></div><?php else:?><p class="empty">No assistance requests yet.</p><?php endif ?></article></div></section><?= $this->endSection() ?>
